on conflict on constraint catalog_courses_session_semester_campus_code_key
do update set
  faculty_code = excluded.faculty_code,
  course_name = excluded.course_name,
  -- Keep credits verified later; a NULL in this seed never erases them.
  credit_hours = coalesce(excluded.credit_hours, public.catalog_courses.credit_hours),
  -- Also keep the label that records where those preserved credits came from.
  source_label = case
    when excluded.credit_hours is null and public.catalog_courses.credit_hours is not null
      then public.catalog_courses.source_label
    else excluded.source_label
  end,
  is_active = excluded.is_active;
